el.safetensors\"\n  echo \"  Trying hf-mirror for model.safetensors...\" | tee -a \"$LOG\"\n  wget --timeout=600 --tries=2 --continue \\\n    \"https://hf-mirror.com/m-a-p/${REPO_NAME}/resolve/main/model.safetensors\" \\\n    -O \"$LOCAL/model.safetensors\" 2>&1 | tail -5 | tee -a \"$LOG\"\n  \n  if [ -f \"$LOCAL/model.safetensors\" ]; then\n    SIZE=$(stat -c%s \"$LOCAL/model.safetensors\")\n    if [ \"$SIZE\" -gt 100000000 ]; then\n      echo \"DOWNLOAD $ARCH DONE via hf-mirror: $SIZE bytes $(date)\" | tee -a \"$LOG\"\n      return 0\n    fi\n  fi\n  \n  # Fallback: Python with HF_ENDPOINT\n  echo \"  hf-mirror wget failed, trying Python with HF_ENDPOINT...\" | tee -a \"$LOG\"\n  rm -f \"$LOCAL/model.safetensors\"\n  python3 -c \"\nimport os\nos.environ['HF_ENDPOINT'] = 'https://hf-mirror.com'\nos.environ['HF_HUB_DISABLE_XET'] = '1'\nfrom huggingface_hub import hf_hub_download\nhf_hub_download(\n    'm-a-p/$REPO_NAME',\n    'model.safetensors',\n    local_dir='$LOCAL',\n    force_download=True,\n)\nprint('OK via Python hf-mirror')\n\" 2>&1 | tee -a \"$LOG\"\n  \n  if [ -f \"$LOCAL/model.safetensors\" ]; then\n    SIZE=$(stat -c%s \"$LOCAL/model.safetensors\")\n    echo \"DOWNLOAD $ARCH DONE: $SIZE bytes $(date)\" | tee -a \"$LOG\"\n  else\n    echo \"DOWNLOAD $ARCH FAILED $(date)\" | tee -a \"$LOG\"\n    return 1\n  fi\n}\n\ndownload_via_mirror \"340M-20B-DeltaNet-pure\" \"$MODELS/340M-20B-DeltaNet-pure\" \"DeltaNet\"\ndownload_via_mirror \"340M-20B-HGRN-pure-baseline\" \"$MODELS/340M-20B-HGRN-pure-baseline\" \"HGRN\"\n\n# ---- VERIFY + EVAL ----\necho \"=== VERIFY ===\" | tee -a \"$LOG\"\ndeclare -A DIRS\nDIRS[GLA]=\"$MODELS/340M-20B-GLA-pure-baseline\"\nDIRS[DeltaNet]=\"$MODELS/340M-20B-DeltaNet-pure\"\nDIRS[HGRN]=\"$MODELS/340M-20B-HGRN-pure-baseline\"\n\nALL_OK=true\nfor ARCH in GLA DeltaNet HGRN; do\n  LOCAL=\"${DIRS[$ARCH]}\"\n  if [ -f \"$LOCAL/model.safetensors\" ]; then\n    SIZE=$(stat -c%s \"$LOCAL/model.safetensors\")\n    echo \"$ARCH: OK ($SIZE bytes