==================\"\n    echo \"[EVAL] $NAME from $LOCAL\"\n    echo \"==========================================\"\n    mkdir -p \"$OUTDIR\"\n\n    python3 -c \"\nimport fla\n# Fix transformers 5.x compatibility: _tied_weights_keys must be dict not list\nimport fla.models.gla.modeling_gla as _gla\nimport fla.models.delta_net.modeling_delta_net as _dn\nimport fla.models.hgrn.modeling_hgrn as _hgrn\nimport fla.models.gated_deltanet.modeling_gated_deltanet as _gdn\n\nfor mod in [_gla, _dn, _hgrn, _gdn]:\n    for attr_name in dir(mod):\n        obj = getattr(mod, attr_name, None)\n        if isinstance(obj, type) and hasattr(obj, '_tied_weights_keys'):\n            if isinstance(obj._tied_weights_keys, list):\n                obj._tied_weights_keys = {'lm_head.weight': 'model.embeddings.weight'}\n\nimport sys\nsys.argv = [\n    'lm_eval',\n    '--model', 'hf',\n    '--model_args', 'pretrained=${LOCAL},trust_remote_code=True',\n    '--tasks', 'lambada_openai,arc_easy',\n    '--device', 'cuda:0',\n    '--batch_size', 'auto',\n    '--log_samples',\n    '--output_path', '${OUTDIR}/',\n]\nfrom lm_eval.__main__ import cli_evaluate\ncli_evaluate()\n\"\n    echo \"[DONE] $NAME eval complete. Results at $OUTDIR\"\n}\n\neval_model \"GLA\" \"$BASEDIR/models/340M-20B-GLA-pure-baseline\"\neval_model \"DeltaNet\" \"$BASEDIR/models/340M-20B-DeltaNet-pure\"\n\n# Step 3: Wait for HGRN download then eval\necho \"[WAIT] Waiting for HGRN download (PID $HGRN_DL_PID)...\"\nwait $HGRN_DL_PID\nHGRN_EXIT=$?\nif [ $HGRN_EXIT -ne 0 ]; then\n    echo \"[ERROR] HGRN download failed with exit code $HGRN_EXIT\"\n    exit 1\nfi\necho \"[DOWNLOAD] HGRN download complete\"\n\neval_model \"HGRN\" \"$BASEDIR/models/340M-20B-HGRN-pure-baseline\"\n\necho \"==========================================\"\necho \"ALL PURE BASELINE EVALS COMPLETE\"\necho \"==========================================\"\nSCRIPT\nchmod +x /root/entrainment_gated_ft/results/exp005_zoo_expansion/run_pure_v9.sh"},"caller":{"type":"dir