grep -q .; then\n        echo \"[SKIP] $NAME already evaluated at $OUTDIR\"\n        return\n    fi\n\n    echo \"==========================================\"\n    echo \"[EVAL] $NAME from $LOCAL\"\n    echo \"==========================================\"\n    mkdir -p \"$OUTDIR\"\n\n    python3 << PYEOF\nimport fla\n# Fix transformers 5.x compatibility\nimport fla.models.gla.modeling_gla as _gla\nimport fla.models.delta_net.modeling_delta_net as _dn\nimport fla.models.hgrn.modeling_hgrn as _hgrn\nimport fla.models.gated_deltanet.modeling_gated_deltanet as _gdn\n\nfor mod in [_gla, _dn, _hgrn, _gdn]:\n    for attr_name in dir(mod):\n        obj = getattr(mod, attr_name, None)\n        if isinstance(obj, type) and hasattr(obj, '_tied_weights_keys'):\n            if isinstance(obj._tied_weights_keys, list):\n                obj._tied_weights_keys = {'lm_head.weight': 'model.embeddings.weight'}\n\nimport sys\nsys.argv = [\n    'lm_eval',\n    '--model', 'hf',\n    '--model_args', 'pretrained=${LOCAL},trust_remote_code=True,dtype=bfloat16',\n    '--tasks', 'lambada_openai,arc_easy',\n    '--device', 'cuda:0',\n    '--batch_size', 'auto',\n    '--log_samples',\n    '--output_path', '${OUTDIR}/',\n]\nfrom lm_eval.__main__ import cli_evaluate\ncli_evaluate()\nPYEOF\n    echo \"[DONE] $NAME eval complete. Results at $OUTDIR\"\n}\n\ntouch /tmp/v10_start_marker\n\n# GLA already has valid results from v9, skip it\n# But check explicitly\nGLA_RESULT=$(find \"$OUTBASE/GLA_pure_baseline\" -name \"results_*.json\" 2>/dev/null | head -1)\nif [ -n \"$GLA_RESULT\" ]; then\n    echo \"[SKIP] GLA already has results: $GLA_RESULT\"\n    # Verify it's valid (acc > 0.1 on lambada)\n    python3 -c \"\nimport json\nwith open('$GLA_RESULT') as f:\n    d = json.load(f)\nacc = d['results']['lambada_openai']['acc,none']\nprint(f'GLA lambada acc={acc:.4f}')\nassert acc > 0.1, 'Invalid GLA results!'\nprint('GLA results VALID')\n\"\nelse\n    eval_model \"GLA\" \"$BASEDIR/models/340M-20B-GLA-pure-b